# Generated by Auto Node Simple: protocol services and minute watchdog.
export PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
[ "$(id -u)" = 0 ] || { echo '请使用 root 执行'; exit 1; }
TMP=$(mktemp -d);OK=0;CONFIG_CHANGED=0
cleanup() {
 code=$?
 if [ "$OK" != 1 ] && [ "$CONFIG_CHANGED" = 1 ];then
  if [ -f "$TMP/previous" ];then cp "$TMP/previous" "$BASE/configs/$NODE_ID.json";else rm -f "$BASE/configs/$NODE_ID.json";fi
  if [ -f "$TMP/previous.link" ];then cp "$TMP/previous.link" "$BASE/state/$NODE_ID.link";else rm -f "$BASE/state/$NODE_ID.link";fi
  for ext in pem key;do [ ! -f "$TMP/previous.$ext" ] || cp "$TMP/previous.$ext" "$BASE/state/$NODE_ID.$ext";done
  if command -v systemctl >/dev/null 2>&1 && [ -d /run/systemd/system ];then systemctl restart auto-node-simple 9>&- >/dev/null 2>&1 || true
  elif command -v rc-service >/dev/null 2>&1;then rc-service auto-node-simple restart 9>&- >/dev/null 2>&1 || true;fi
 fi
 if [ "$OK" != 1 ] && command -v curl >/dev/null && command -v jq >/dev/null; then
  jq -n '{error:"安装未完成，请查看终端输出后重试；已完成的协议不会自动删除。"}' > "$TMP/error.json"
  curl -fsS --connect-timeout 3 --max-time 6 -H 'Content-Type: application/json' --data-binary @"$TMP/error.json" "$PANEL/result/$INSTALL_ID/$CALLBACK_TOKEN" >/dev/null 2>&1 || true
 fi
 rm -rf "$TMP";exit "$code"
}
trap cleanup EXIT
. /etc/os-release
case "$ID" in alpine|debian|ubuntu) ;; *) echo '仅支持 Alpine / Debian / Ubuntu';exit 1;; esac
if [ -d /run/systemd/system ] && command -v systemctl >/dev/null; then INIT=systemd
elif command -v rc-service >/dev/null; then INIT=openrc
else echo '需要 systemd 或 OpenRC';exit 1;fi
missing=''
for tool in curl jq openssl flock ss timeout;do command -v "$tool" >/dev/null 2>&1 || missing="$missing $tool";done
if [ -n "$missing" ] || [ ! -s /etc/ssl/certs/ca-certificates.crt ];then
 echo '安装必要依赖…'
 case "$ID" in
 alpine) apk add --no-cache curl jq openssl ca-certificates iproute2-ss ;;
 *) apt-get update -qq;DEBIAN_FRONTEND=noninteractive apt-get install -y --no-install-recommends curl jq openssl ca-certificates util-linux iproute2 ;;
 esac
fi
printf '%s' "$PAYLOAD" | base64 -d > "$TMP/options"
printf '%s' "$MANIFEST" | base64 -d > "$TMP/manifest"
KIND=$(jq -r .protocol "$TMP/options");PORT=$(jq -r .port "$TMP/options");SNI=$(jq -r .sni "$TMP/options")
CREDENTIAL=$(jq -r .credential "$TMP/options");WS_PATH=$(jq -r .path "$TMP/options")
TUNNEL=$(jq -r .tunnel "$TMP/options")
case "$(uname -m)" in x86_64|amd64) ARCH=amd64;; aarch64|arm64) ARCH=arm64;; *) echo '仅支持 amd64 / arm64';exit 1;; esac
BASE=/usr/local/etc/auto-node-simple
mkdir -p "$BASE/configs" "$BASE/state" /usr/local/lib/auto-node-simple
chmod 700 "$BASE" "$BASE/configs" "$BASE/state"
exec 9>/run/auto-node-simple.lock
# BusyBox flock has no -w. timeout bounds the wait while FD 9 stays owned
# by this shell, so the lock also covers downloads and service changes.
if timeout 120 flock 9;then :
else
 code=$?
 case "$code" in
  124|137|143) echo '等待同机安装锁超时，请确认其他安装已结束后重试' ;;
  *) echo "安装锁获取失败（退出码 $code），不是其他任务占用提示；请检查 flock / timeout 命令" ;;
 esac
 exit 1
fi
BIN=/usr/local/bin/auto-node-singbox
fetch() {
 asset=$1;target=$2;expected=$(jq -er --arg n "$asset" '.[$n].sha256' "$TMP/manifest")
 if [ -x "$target" ] && [ "$(sha256sum "$target" | cut -d ' ' -f1)" = "$expected" ];then return;fi
 echo "下载 $asset…"
 curl -fL --retry 1 --connect-timeout 10 --max-time 180 "$PANEL/assets/$asset" -o "$TMP/binary"
 printf '%s  %s\n' "$expected" "$TMP/binary" | sha256sum -c -
 chmod 755 "$TMP/binary";mv "$TMP/binary" "$target"
}
fetch "sing-box-$ARCH" "$BIN"
if [ "$KIND" = argo ];then fetch "cloudflared-$ARCH" /usr/local/bin/auto-node-cloudflared;fi
OLD_PORT=''
if [ -f "$BASE/configs/$NODE_ID.json" ];then
 jq -e --arg u "$CREDENTIAL" '[.inbounds[]?.users[]? | (.uuid // .password)] | length>0 and all(.==$u)' "$BASE/configs/$NODE_ID.json" >/dev/null || { echo '原节点认证信息不匹配，拒绝覆盖';exit 1; }
 OLD_PORT=$(jq -r '.inbounds[0].listen_port' "$BASE/configs/$NODE_ID.json")
fi
NET=tcp;[ "$KIND" != hysteria2 ] || NET=udp
if ss -H -ln"$( [ "$NET" = tcp ] && printf t || printf u )" | awk '{print $4}' | grep -Eq ":${PORT}$" && [ "$OLD_PORT" != "$PORT" ];then
 echo "端口 $PORT/$NET 已被占用，请改用其他端口";exit 1
fi
[ -f "$BASE/configs/base.json" ] || printf '%s\n' '{"log":{"level":"warn"},"outbounds":[{"type":"direct","tag":"direct"}],"route":{"final":"direct"}}' > "$BASE/configs/base.json"
TAG="simple-$NODE_ID"
PUBLIC='';SID=''
case "$KIND" in
argo)
 jq -n --arg t "$TAG" --argjson p "$PORT" --arg u "$CREDENTIAL" --arg path "$WS_PATH" '{inbounds:[{type:"vless",tag:$t,listen:"127.0.0.1",listen_port:$p,users:[{uuid:$u}],transport:{type:"ws",path:$path}}]}' > "$TMP/inbound" ;;
reality)
 if [ -f "$BASE/configs/$NODE_ID.json" ];then
  PRIVATE=$(jq -r '.inbounds[0].tls.reality.private_key // empty' "$BASE/configs/$NODE_ID.json")
  SID=$(jq -r '.inbounds[0].tls.reality.short_id[0] // empty' "$BASE/configs/$NODE_ID.json")
  PUBLIC=$(sed -n 's/.*[?&]pbk=\([^&#]*\).*/\1/p' "$BASE/state/$NODE_ID.link")
  [ -n "$PRIVATE" ] && [ -n "$SID" ] && [ -n "$PUBLIC" ] || { echo '原 Reality 密钥资料不完整，拒绝生成新身份';exit 1; }
 else
  "$BIN" generate reality-keypair > "$TMP/keypair"
  PRIVATE=$(awk '/PrivateKey/ {print $2}' "$TMP/keypair");PUBLIC=$(awk '/PublicKey/ {print $2}' "$TMP/keypair");SID=$(openssl rand -hex 8)
 fi
 [ -n "$PRIVATE" ] && [ -n "$PUBLIC" ]
 jq -n --arg t "$TAG" --argjson p "$PORT" --arg u "$CREDENTIAL" --arg s "$SNI" --arg k "$PRIVATE" --arg sid "$SID" '{inbounds:[{type:"vless",tag:$t,listen:"::",listen_port:$p,users:[{uuid:$u,flow:"xtls-rprx-vision"}],tls:{enabled:true,server_name:$s,reality:{enabled:true,handshake:{server:$s,server_port:443},private_key:$k,short_id:[$sid]}}}]}' > "$TMP/inbound" ;;
hysteria2)
 for ext in pem key;do [ ! -f "$BASE/state/$NODE_ID.$ext" ] || cp "$BASE/state/$NODE_ID.$ext" "$TMP/previous.$ext";done
 if [ ! -s "$BASE/state/$NODE_ID.key" ] || ! openssl x509 -noout -checkhost "$SNI" -in "$BASE/state/$NODE_ID.pem" >/dev/null 2>&1;then
 openssl req -x509 -nodes -newkey ec -pkeyopt ec_paramgen_curve:P-256 -keyout "$BASE/state/$NODE_ID.key" -out "$BASE/state/$NODE_ID.pem" -days 3650 -subj "/CN=$SNI" -addext "subjectAltName=DNS:$SNI" >/dev/null 2>&1
 fi
 jq -n --arg t "$TAG" --argjson p "$PORT" --arg u "$CREDENTIAL" --arg s "$SNI" --arg cert "$BASE/state/$NODE_ID.pem" --arg key "$BASE/state/$NODE_ID.key" '{inbounds:[{type:"hysteria2",tag:$t,listen:"::",listen_port:$p,users:[{password:$u}],tls:{enabled:true,server_name:$s,alpn:["h3"],certificate_path:$cert,key_path:$key}}]}' > "$TMP/inbound" ;;
esac
[ ! -f "$BASE/configs/$NODE_ID.json" ] || cp "$BASE/configs/$NODE_ID.json" "$TMP/previous"
[ ! -f "$BASE/state/$NODE_ID.link" ] || cp "$BASE/state/$NODE_ID.link" "$TMP/previous.link"
CONFIG_CHANGED=1
mv "$TMP/inbound" "$BASE/configs/$NODE_ID.json"
if ! "$BIN" check -C "$BASE/configs";then
 if [ -f "$TMP/previous" ];then cp "$TMP/previous" "$BASE/configs/$NODE_ID.json";else rm -f "$BASE/configs/$NODE_ID.json";fi
 exit 1
fi
service_file() {
 name=$1;cmd=$2;args=$3
 if [ "$INIT" = systemd ];then
  cat > "/etc/systemd/system/$name.service" <<EOF
[Unit]
Description=Auto Node Simple $name
After=network-online.target
Wants=network-online.target
[Service]
ExecStart=$cmd $args
Restart=on-failure
RestartSec=3
Environment=GOMAXPROCS=1
LimitNOFILE=65535
[Install]
WantedBy=multi-user.target
EOF
  : # The shared watchdog installer reloads all newly written units once.
 else
  cat > "/etc/init.d/$name" <<EOF
#!/sbin/openrc-run
name="$name"
command="$cmd"
command_args="$args"
command_background=true
pidfile="/run/$name.pid"
output_log="$BASE/state/$name.log"
error_log="$BASE/state/$name.log"
export GOMAXPROCS=1
depend() { need net; }
EOF
  chmod 755 "/etc/init.d/$name"
 fi
}
echo '写入协议服务配置…'
service_file auto-node-simple "$BIN" "run -C $BASE/configs"
DOMAIN=$SNI
if [ "$KIND" = argo ];then
 [ "$TUNNEL" = fixed ] || { echo '临时隧道已移除，请使用固定隧道';exit 1; }
 jq -r .tunnel_token "$TMP/options" > "$BASE/state/$NODE_ID.token"
 DOMAIN=$(jq -r .tunnel_hostname "$TMP/options")
 ARGS="tunnel --no-autoupdate run --token-file $BASE/state/$NODE_ID.token"
 service_file "auto-node-$NODE_ID" /usr/local/bin/auto-node-cloudflared "$ARGS"
fi
ADDRESS=$(jq -r .address "$TMP/options");[ -n "$ADDRESS" ] || ADDRESS=$DOMAIN
case "$ADDRESS" in *:*) ADDRESS="[$ADDRESS]";; esac
CP=$(jq -r .client_port "$TMP/options")
case "$KIND" in argo) SUFFIX=-CF;;reality) SUFFIX=-Vless;;hysteria2) SUFFIX=-hy2;;esac
NAME=$(jq -r --arg suffix "$SUFFIX" '(.name | if $suffix == "-CF" and endswith("-cf") then .[0:-3]+"-CF" else . end | if endswith($suffix) then . else .+$suffix end)|@uri' "$TMP/options")
if [ "$KIND" = argo ];then LINK="vless://$CREDENTIAL@$ADDRESS:$CP?encryption=none&security=tls&type=ws&host=$DOMAIN&sni=$DOMAIN&path=$(printf '%s' "$WS_PATH" | jq -sRr @uri)&fp=chrome#$NAME"
elif [ "$KIND" = reality ];then LINK="vless://$CREDENTIAL@$ADDRESS:$CP?encryption=none&security=reality&type=tcp&flow=xtls-rprx-vision&sni=$SNI&pbk=$PUBLIC&sid=$SID&fp=chrome#$NAME"
else LINK="hysteria2://$CREDENTIAL@$ADDRESS:$CP?sni=$SNI&insecure=1&alpn=h3#$NAME";fi
printf '%s\n' "$LINK" > "$BASE/state/$NODE_ID.link"
# Existing watchers keep their credential and disabled/paused state on updates.
if [ "$REPAIR_KEEP_TOKEN" = 1 ] && [ ! -s "$BASE/repair/$NODE_ID/curl.conf" ];then REPAIR_KEEP_TOKEN=0;fi
printf '%s' "$REPAIR_INSTALLER" | base64 -d > "$TMP/repair-setup.sh"
PANEL="$PANEL" NODE_ID="$NODE_ID" REPORT_TOKEN="$REPORT_TOKEN" REPAIR_KEEP_TOKEN="$REPAIR_KEEP_TOKEN" REPAIR_INSTALL_LOCKED=1 REPAIR_DEFER_REPORT=1 sh "$TMP/repair-setup.sh"
# Units for the core, tunnel and shared timer are now loaded in one daemon-reload.
start_service() {
 if [ "$INIT" = systemd ];then
  systemctl enable "$1" >/dev/null;systemctl restart "$1" 9>&-;systemctl is-active --quiet "$1"
 else
  rc-update add "$1" default >/dev/null;rc-service "$1" restart 9>&-
 fi
}
echo '启动协议服务…'
start_service auto-node-simple
if [ "$KIND" = argo ];then start_service "auto-node-$NODE_ID";fi
jq -n --arg link "$LINK" --argjson kept "$( [ "$REPAIR_KEEP_TOKEN" = 1 ] && printf true || printf false )" '{link:$link,repair_installed:true,repair_token_kept:$kept}' > "$TMP/result"
OK=1
CALLBACK_OK=0
if curl -fsS --retry 2 --retry-all-errors --connect-timeout 5 --max-time 30 -H 'Content-Type: application/json' --data-binary @"$TMP/result" "$PANEL/result/$INSTALL_ID/$CALLBACK_TOKEN" >/dev/null;then CALLBACK_OK=1
else echo '结果回传失败，巡检尚不能授权修复；请重试本安装命令完成回传。';fi
flock -u 9
if [ "$CALLBACK_OK" = 1 ];then /bin/sh /usr/local/lib/auto-node-simple/watchdog.sh "$NODE_ID" 9>&- || true;fi
printf '\n安装完成（未执行公网测活），节点链接：\n%s\n' "$LINK"
echo '协议与轻量巡检已一起安装。每分钟短任务，无常驻巡检进程；可在节点管理中停用修复。'
